# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student


def _require_email(student: Student) -> str:
    email = (student.email or "").strip()
    if not email:
        raise ValueError(f"no email for {student.display_name}")
    return email


def _align(names: List[str], sections: List[str], emails: List[str]) -> List[str]:
    name_wide = max(len(text) for text in names)
    sect_wide = max(len(text) for text in sections)
    return [
        f"{name:<{name_wide}}  {sect:<{sect_wide}}  {mail}"
        for name, sect, mail in zip(names, sections, emails)
    ]


# ---
def format_contact_sheet(students: Iterable[Student]) -> List[str]:
    """Text rows of name, section and email, sorted by display name."""
    ordered = sorted(students, key=lambda item: item.display_name.lower())
    if not ordered:
        raise ValueError("no students for the contact sheet")
    emails = [_require_email(item) for item in ordered]
    names = [item.display_name for item in ordered]
    return _align(names, [item.section for item in ordered], emails)

