# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import format_contact_sheet


# ---
def make_student(last, first, section, email):
    return Student("id-" + last, last, first, section, email)


class ContactSheetTests(unittest.TestCase):
    def setUp(self):
        self.thistle = make_student("Thistle", "Bram", "A", "bthistle@example.edu")
        self.dunmere = make_student("Dunmere", "Piet", "Bravo", "pdunmere@example.edu")

    def test_rows_are_sorted_and_aligned(self):
        rows = format_contact_sheet([self.thistle, self.dunmere])
        self.assertEqual(
            rows,
            [
                "Dunmere, Piet  Bravo  pdunmere@example.edu",
                "Thistle, Bram  A      bthistle@example.edu"
            ]
        )

    def test_missing_email_names_the_student(self):
        nomail = make_student("Quillon", "Sefa", "A", None)
        with self.assertRaises(ValueError) as caught:
            format_contact_sheet([self.thistle, nomail])
        self.assertIn("Quillon, Sefa", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        blank = make_student("Varrow", "Ines", "A", "  ")
        with self.assertRaises(ValueError):
            format_contact_sheet([blank])

    def test_empty_list_is_rejected(self):
        with self.assertRaises(ValueError):
            format_contact_sheet([])
